// func simdExecBatchDeltaNEON(dst *byte, lits *byte, tok *byte, ll *byte, offc *byte, raw *byte, esc *byte, n int, st *[4]int)
TEXT ·simdExecBatchDeltaNEON(SB), NOSPLIT, $0-72
	MOVD dst+0(FP), DST
	MOVD lits+8(FP), LITP
	MOVD tok+16(FP), TOKP
	MOVD ll+24(FP), LLP
	MOVD offc+32(FP), OFFP
	MOVD raw+40(FP), RAW
	MOVD esc+48(FP), ESCP
	MOVD n+56(FP), LEFT
	MOVD ZR, POS
	MOVD st+64(FP), ST
	MOVD (ST), DP
	ADD DST, DP
	MOVD 8(ST), R14
	ADD R14, LITP
	MOVD 16(ST), LAST
	MOVD $·simdOffTabNEON(SB), OFFTAB
	MOVD $·simdPermTabNEON(SB), PERMTAB
	MOVD $0x0101010101010101, ONES
	CBZ LEFT, done
	MOVD (TOKP), R14
	LSR $1, R14, R15
	AND ONES, R15
	MUL ONES, R15, R16
	SUB R15, R16, R13
	EOR ONES, R15
	ORR R15<<7, R13
	FMOVD R13, F16
	FMOVD (LLP), F17
	VTBL V16.B8, [V17.B16], V16.B8
	FMOVD F16, LWN
	ADD R16>>56, LLP
	BIC R14, ONES, R15
	MUL ONES, R15, R16
	SUB R15, R16, R13
	EOR ONES, R15
	ORR R15<<7, R13
	FMOVD R13, F18
	FMOVD (OFFP), F19
	VTBL V18.B8, [V19.B16], V18.B8
	FMOVD F18, SWN
	ADD R16>>56, OFFP
	// LEFT is the number of operations left, from TOKP on.
	PCALIGN $64

loop:
	CMP $8, LEFT
	BLO tail
	MOVD.P 8(TOKP), TW
	MOVD LWN, LW
	MOVD SWN, SW
	SUBS $8, LEFT
	BEQ batch
	MOVD (TOKP), R14
	LSR $1, R14, R15
	AND ONES, R15
	MUL ONES, R15, R16
	SUB R15, R16, R13
	EOR ONES, R15
	ORR R15<<7, R13
	FMOVD R13, F16
	FMOVD (LLP), F17
	VTBL V16.B8, [V17.B16], V16.B8
	FMOVD F16, LWN
	ADD R16>>56, LLP
	BIC R14, ONES, R15
	MUL ONES, R15, R16
	SUB R15, R16, R13
	EOR ONES, R15
	ORR R15<<7, R13
	FMOVD R13, F18
	FMOVD (OFFP), F19
	VTBL V18.B8, [V19.B16], V18.B8
	FMOVD F18, SWN
	ADD R16>>56, OFFP

batch:
	UBFX $0, TW, $8, TOK
