TEXT ·simdExecBatchFlatDeltaNEON(SB), NOSPLIT, $0-80
	MOVD dst+0(FP), DST
	MOVD lits+8(FP), LITP
	MOVD tok+16(FP), TOKP
	MOVD ll+24(FP), LLP
	MOVD offc+32(FP), OFFP
