	MOVD pos+64(FP), POS
	MOVD (ST), DP
	ADD DST, DP
	MOVD 8(ST), R14
	ADD R14, LITP
	MOVD 16(ST), LAST
	MOVD $·simdOffTabNEON(SB), OFFTAB
	MOVD $·simdPermTabNEON(SB), PERMTAB
	MOVD $0x0101010101010101, ONES
	MOVD $32, C32
	CBZ LEFT, done
	MOVD (TOKP), R14
	LSR $1, R14, R15
	AND ONES, R15
	MUL ONES, R15, R16
	SUB R15, R16, R13
	EOR ONES, R15
	ORR R15<<7, R13
	FMOVD R13, F16
	FMOVD (LLP), F17
	VTBL V16.B8, [V17.B16], V16.B8
	FMOVD F16, LWN
	ADD R16>>56, LLP
	BIC R14, ONES, R15
	MUL ONES, R15, R16
